'use strict';

// MODULES //

var kernelCosf = require( '@stdlib/math/base/special/kernel-cosf' );
var kernelSinf = require( '@stdlib/math/base/special/kernel-sinf' );
var rempio2f = require( '@stdlib/math/base/special/rempio2f' );
var toWordf = require( '@stdlib/number/float32/base/to-word' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var FLOAT32_ABS_MASK = require( '@stdlib/constants/float32/abs-mask' );
var FLOAT32_EXPONENT_MASK = require( '@stdlib/constants/float32/exponent-mask' );
var FLOAT64_HALF_PI = require( '@stdlib/constants/float64/half-pi' );


// VARIABLES //

// High word for PI/4: 0x3f490fda = 1061752794 => 00111111010010010000111111011010
var PIO4_HIGH_WORD = 0x3f490fda|0; // asm type annotation

// High word for 3*PI/4: 0x4016cbe3 = 1075235811 => 01000000000101101100101111100011
var PIO3_HIGH_WORD = 0x4016cbe3|0; // asm type annotation

// High word for 5*PI/4: 0x407b53d1 = 1081824209 => 01000000011110110101001111010001
var PIO5_HIGH_WORD = 0x407b53d1|0; // asm type annotation

// High word for 7*PI/4: 0x40afeddf = 1085271519 => 01000000101011111110110111011111
var PIO7_HIGH_WORD = 0x40afeddf|0; // asm type annotation

// High word for 9*PI/4: 0x40e231d5 = 1088565717 => 01000000111000100011000111010101
var PIO9_HIGH_WORD = 0x40e231d5|0; // asm type annotation

// 2^-12 = 2.44140625e-5 => 0011111100110000000000000000000000000000000000000000000000000000 => high word => 00111111001100000000000000000000 => 0x3f300000 = 1060110336
var SMALL_HIGH_WORD = 0x39800000|0; // asm type annotation

// Small multiples of PI/2 in double-precision floating-point format:
var PIO2 = FLOAT64_HALF_PI;             // 0x3FF921FB, 0x54442D18
var PI = 2.0 * FLOAT64_HALF_PI;         // 0x400921FB, 0x54442D18
var THREE_PIO2 = 3.0 * FLOAT64_HALF_PI; // 0x4012D97C, 0x7F3321D2
var TWO_PI = 4.0 * FLOAT64_HALF_PI;     // 0x401921FB, 0x54442D18

// Array for storing the remainder element:
var Y = [ 0.0 ];


// MAIN //

/**
* Computes the sine of a single-precision floating-point number (in radians).
*
* ## Method
*
* -   Let \\(S\\), \\(C\\), and \\(T\\) denote the \\(\sin\\), \\(\cos\\), and \\(\tan\\), respectively, on \\(\[-\pi/4, +\pi/4\]\\).
*
* -   Reduce the argument \\(x\\) to \\(y = x-k\pi/2\\) in \\(\[-\pi/4, +\pi/4\]\\), and let \\(n = k \mod 4\\).
*
* -   We have
*
*     | n | sin(x) | cos(x) | tan(x) |
*     | - | ------ | ------ | ------ |
*     | 0 |   S    |   C    |    T   |
*     | 1 |   C    |  -S    |  -1/T  |
*     | 2 |  -S    |  -C    |    T   |
*     | 3 |  -C    |   S    |  -1/T  |
*
* @param {number} x - input value (in radians)
* @returns {number} sine
*
* @example
* var v = sinf( 0.0 );
* // returns ~0.0
*
* @example
* var v = sinf( 3.141592653589793/2.0 );
* // returns ~1.0
*
* @example
* var v = sinf( -3.141592653589793/6.0 );
* // returns ~-0.5
*
* @example
* var v = sinf( NaN );
* // returns NaN
*/
function sinf( x ) {
	var ix;
	var n;

	ix = toWordf( f32( x ) );
	ix &= FLOAT32_ABS_MASK;

	// Case: |x| ~<= π/4
	if ( ix <= PIO4_HIGH_WORD ) {
		// Case: |x| < 2^-12
		if ( ix < SMALL_HIGH_WORD ) {
			return f32( x );
		}
		return kernelSinf( x );
	}
	// Case: |x| ~<= 5π/4
	if ( ix <= PIO5_HIGH_WORD ) {
		// Case: |x| ~<= 3π/4
		if ( ix <= PIO3_HIGH_WORD ) {
			if ( x > 0 ) {
				return f32( kernelCosf( x - PIO2 ) );
			}
			return f32( -kernelCosf( x + PIO2 ) );
		} else {
			if ( x > 0 ) {
				return f32( kernelSinf( PI - x ) );
			}
			return f32( -kernelSinf( PI + x ) );
		}
	}
	// Case: |x| ~<= 9π/4
	if ( ix <= PIO9_HIGH_WORD ) {
		// Case: |x| ~<= 7π/4
		if ( ix <= PIO7_HIGH_WORD ) {
			if ( x > 0 ) {
				return f32( -kernelCosf( x - THREE_PIO2 ) );
			}
			return f32( kernelCosf( x + THREE_PIO2 ) );
		} else {
			if ( x > 0 ) {
				return f32( kernelSinf( x - TWO_PI ) );
			}
			return f32( kernelSinf( x + TWO_PI ) );
		}
	}
	// Case: x is NaN or infinity
	if ( ix >= FLOAT32_EXPONENT_MASK ) {
		return NaN;
	}
	// Argument reduction...
	n = rempio2f( x, Y );
	switch ( n & 3 ) {
	case 0:
		return f32( kernelSinf( Y[ 0 ] ) );
	case 1:
		return f32( kernelCosf( Y[ 0 ] ) );
	case 2:
		return f32( -kernelSinf( Y[ 0 ] ) );
	default:
		return f32( -kernelCosf( Y[ 0 ] ) );
	}
}


// EXPORTS //

module.exports = sinf;
